      style={{ color: colors.muted, fontSize: "15px", lineHeight: "24px", margin: "0 0 24px" }}
    >
      {children}
    </Text>
  );
}

/** The dark call-to-action button. */
export function PrimaryButton({ href, children }: { href: string; children: ReactNode }) {
  return (
